import { n as generateCards, t as fillColdStartCards } from "./assets/recommend-6q_kLZql.js";
//#region scripts/live-check.mjs
/**
* Live smoke check against the running backend.
*
* Confirms the recommender produces differentiated cards from real catalogue
* data rather than only from fixtures. Run with the backend on port 3001.
*/
var shelves = await (await fetch("http://localhost:3001/api/shelves?limit=8")).json();
console.log("shelves:", shelves.length, "| tracks:", shelves.reduce((n, s) => n + (s.tracks?.length ?? 0), 0));
var all = shelves.flatMap((s) => s.tracks ?? []);
var byLanguage = (code) => all.filter((t) => t.language === code);
var ml = byLanguage("ml");
var scriptPresent = all.filter((t) => /[\u0D00-\u0D7F]/.test(t.title)).length;
console.log(`malayalam (by language field): ${ml.length} | native-script titles: ${scriptPresent} | other: ${all.length - ml.length}`);
var now = Date.now();
var history = ml.slice(0, 5).flatMap((t, i) => [{
	...t,
	playCount: 4,
	skipCount: 0,
	completionRate: .95,
	liked: i < 2,
	lastPlayedAt: now - 36e5
}, {
	...t,
	playCount: 2,
	skipCount: 1,
	completionRate: .4,
	liked: false,
	lastPlayedAt: now - 72e5
}]);
var likedSongs = ml.slice(0, 2).map((t) => ({
	...t,
	likedAt: now
}));
var { cards, profile, catalogue } = generateCards({
	shelves,
	history,
	likedSongs
});
var filled = fillColdStartCards({
	cards,
	catalogue,
	profile
});
console.log("tier:", profile.level.tier, "| plays:", profile.totals.plays, "| liked:", profile.totals.liked);
console.log("");
for (const c of filled) {
	console.log(`${c.card.padEnd(12)} ${String(c.count).padStart(2)} songs  [${c.tier}]  ${c.subtitle}`);
	for (const s of c.songs.slice(0, 3)) console.log(`    ${(s.score ?? 0).toFixed(1).padStart(5)}  ${(s.title ?? "").slice(0, 32).padEnd(34)} ${s.reason}`);
}
var sigs = filled.filter((c) => c.count).map((c) => c.songs.map((s) => s.id).join(","));
console.log("");
console.log("distinct card outputs:", new Set(sigs).size, "of", sigs.length);
var wrongLanguage = filled.find((c) => c.key === "malayalam").songs.filter((s) => s.track && s.track.language && s.track.language !== "ml");
console.log("malayalam card wrong-language tracks:", wrongLanguage.length);
if (wrongLanguage.length > 0) {
	for (const s of wrongLanguage) console.log(`    LEAK ${s.track.language} ${s.track.title}`);
	console.log("\nFAIL: the Malayalam card contains non-Malayalam tracks");
	process.exitCode = 1;
} else console.log("ok   every Malayalam card track is backend-classified as ml");
//#endregion
export {};
